// internal/lang/golang.go
func (goLang) Imports(path string, src []byte) ([]Import, error) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, path, src, parser.ImportsOnly)
	if err != nil {
		return nil, err
	}
	var out []Import
	for _, imp := range f.Imports {
		p, uerr := strconv.Unquote(imp.Path.Value)
		if uerr != nil {
			continue
		}
		out = append(out, Import{Raw: p, Line: fset.Position(imp.Pos()).Line})
	}
	return out, nil
}

// Resolve strips the module prefix to get a repo-relative path; external imports (and the
// bare module root) resolve to "".
func (goLang) Resolve(raw, _ string, cfg *config.Config) string {
	if cfg.Module == "" || raw == cfg.Module {
		return ""
	}
	if strings.HasPrefix(raw, cfg.Module+"/") {
		return strings.TrimPrefix(raw, cfg.Module+"/")
	}
	return ""
}

// internal/lang/typescript.go
var (
	tsFrom    = regexp.MustCompile(`(?:^|[^.\w])(?:import|export)\b[^'\"]*?\bfrom\s*['\"]([^'\"]+)['\"]`)
	tsBare    = regexp.MustCompile(`(?:^|[^.\w])import\s+['\"]([^'\"]+)['\"]`)
	tsRequire = regexp.MustCompile(`(?:^|[^.\w])require\s*\(\s*['\"]([^'\"]+)['\"]\s*\)`)
	tsDynamic = regexp.MustCompile(`(?:^|[^.\w])import\s*\(\s*['\"]([^'\"]+)['\"]\s*\)`)
)

func (tsLang) Imports(_ string, src []byte) ([]Import, error) {
	var out []Import
	for _, re := range []*regexp.Regexp{tsFrom, tsBare, tsRequire, tsDynamic} {
		for _, m := range re.FindAllSubmatchIndex(src, -1) {
			out = append(out, Import{Raw: string(src[m[2]:m[3]]), Line: lineAt(src, m[2])})
		}
	}
	return out, nil
}

func (tsLang) Resolve(raw, fileRel string, cfg *config.Config) string {
	if strings.HasPrefix(raw, "./") || strings.HasPrefix(raw, "../") {
		return clean(path.Join(path.Dir(toSlash(fileRel)), raw))
	}
	if target, ok := applyAlias(raw, cfg); ok {
		return clean(target)
	}
	return "" // bare / external
}

// internal/lang/python.go
var (
	// `from <module> import …` — captures the dotted module, including leading dots.
	pyFrom = regexp.MustCompile(`(?m)^[ \t]*from[ \t]+(\.*[\w.]*)[ \t]+import\b`)
	// `import a.b, c.d as e` — captures the comma-separated module list (sans comment).
	pyImport = regexp.MustCompile(`(?m)^[ \t]*import[ \t]+([^\n#]+)`)
)

func (pyLang) Imports(_ string, src []byte) ([]Import, error) {
	var out []Import

	for _, m := range pyFrom.FindAllSubmatchIndex(src, -1) {
		mod := string(src[m[2]:m[3]])
		if mod == "" {
			continue
		}
		out = append(out, Import{Raw: mod, Line: lineAt(src, m[2])})
	}

	for _, m := range pyImport.FindAllSubmatchIndex(src, -1) {
		line := lineAt(src, m[2])
		for _, part := range strings.Split(string(src[m[2]:m[3]]), ",") {
			mod := strings.TrimSpace(part)
			if i := strings.Index(mod, " as "); i >= 0 {
				mod = mod[:i]
			}
			fields := strings.Fields(mod)
			if len(fields) == 0 {
				continue
			}
			out = append(out, Import{Raw: fields[0], Line: line})
		}
	}
	return out, nil
}

// Resolve maps a module to a repo-relative path. Relative imports (leading dots) resolve
// against the importing file's package; absolute imports map dotted→slash, with an optional
// alias prefix for src-layout roots. External/stdlib modules resolve to a path that simply
// matches no layer.
func (pyLang) Resolve(raw, fileRel string, cfg *config.Config) string {
	if strings.HasPrefix(raw, ".") {
		n := 0
		for n < len(raw) && raw[n] == '.' {
			n++
		}
		base := path.Dir(toSlash(fileRel))
		for i := 1; i < n; i++ { // 1 dot = current package; each extra dot goes up one
			base = path.Dir(base)
		}
		rest := raw[n:]
		if rest == "" {
			return clean(base)
		}
		return clean(path.Join(base, strings.ReplaceAll(rest, ".", "/")))
	}

	slashed := strings.ReplaceAll(raw, ".", "/")
	if target, ok := applyAlias(slashed, cfg); ok {
		return clean(target)
	}
	return clean(slashed)
}
